package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/url"
	"os/exec"
	"runtime"
	"time"

	apiurl "github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/spf13/cobra"
)

const fallbackDeviceAuthPollInterval = time.Second
const slowDownBackoff = 5 * time.Second
const maxPollInterval = 30 * time.Second
const maxExpiresIn = 15 * time.Minute
const maxTransientErrors = 5

// browserOpenFunc is the signature for opening a URL in the user's browser.
type browserOpenFunc func(ctx context.Context, url string) error

// deviceAuthClient abstracts the auth client so runLogin and waitForApproval can be unit-tested.
type deviceAuthClient interface {
	StartDeviceAuth(ctx context.Context) (*auth.DeviceAuthStart, error)
	PollDeviceAuth(ctx context.Context, deviceCode string) (*auth.DeviceAuthPoll, error)
	BaseURL() string
}

func newLoginCmd() *cobra.Command {
	var printBrowserURL bool
	var insecureHTTPAuth bool

	cmd := &cobra.Command{
		Use:   "login",
		Short: "Log in to Entire",
		RunE: func(cmd *cobra.Command, _ []string) error {
			client := auth.NewClient(nil)

			if !insecureHTTPAuth {
				if err := apiurl.RequireSecureURL(client.BaseURL()); err != nil {
					return fmt.Errorf("base URL check: %w", err)
				}
			}

			return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), client, openBrowser, printBrowserURL)
		},
	}

	cmd.Flags().BoolVar(&printBrowserURL, "print-browser-url", false, "Print the approval URL instead of opening a browser")
	cmd.Flags().BoolVar(&insecureHTTPAuth, "insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
	if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
		panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
	}

	return cmd
}

func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc, printBrowserURL bool) error {
	start, err := client.StartDeviceAuth(ctx)
	if err != nil {
		return fmt.Errorf("start login: %w", err)
	}

	fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
	approvalURL := start.VerificationURIComplete
	if approvalURL == "" {
		approvalURL = start.VerificationURI
	}

	fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)

	if printBrowserURL {
		fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
	} else {
		if err := openURL(ctx, approvalURL); err != nil {
			fmt.Fprintf(errW, "Warning: failed to open browser automatically: %v\n", err)
			fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
		} else {
			fmt.Fprintln(outW, "Opened your browser for approval.")
		}
	}

	fmt.Fprintln(outW, "Waiting for approval...")

	token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, start.Interval)
	if err != nil {
		return fmt.Errorf("complete login: %w", err)
	}

	store := auth.NewStore()

	if err := store.SaveToken(client.BaseURL(), token); err != nil {
		return fmt.Errorf("save auth token: %w", err)
	}

	fmt.Fprintln(outW, "Login complete.")
	return nil
}

func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
	expiry := time.Duration(expiresIn) * time.Second
	if expiry <= 0 || expiry > maxExpiresIn {
		expiry = maxExpiresIn
	}
	deadline := time.Now().Add(expiry)
	pollInterval := time.Duration(interval) * time.Second
	if pollInterval <= 0 {
		pollInterval = fallbackDeviceAuthPollInterval
	}

	consecutiveErrors := 0

	for {
		if time.Now().After(deadline) {
			return "", errors.New("device authorization expired")
		}

		result, err := poller.PollDeviceAuth(ctx, deviceCode)
		if err != nil {
			consecutiveErrors++
			if consecutiveErrors >= maxTransientErrors {
				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
			}
			// Transient error — wait and retry.
			select {
			case <-ctx.Done():
				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
			case <-time.After(pollInterval):
			}
			continue
		}
		consecutiveErrors = 0

		switch result.Error {
		case "":
			if result.AccessToken == "" {
				return "", errors.New("device authorization completed without a token")
			}
			return result.AccessToken, nil
		case "authorization_pending":
			// no-op, will sleep and retry below
		case "slow_down":
			pollInterval += slowDownBackoff
			if pollInterval > maxPollInterval {
				pollInterval = maxPollInterval
			}
		case "access_denied":
			return "", errors.New("device authorization denied")
		case "expired_token":
			return "", errors.New("device authorization expired")
		default:
			return "", fmt.Errorf("device authorization failed: %s", result.Error)
		}

		select {
		case <-ctx.Done():
			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
		case <-time.After(pollInterval):
		}
	}
}

func openBrowser(ctx context.Context, browserURL string) error {
	u, err := url.Parse(browserURL)
	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
	}

	var command string
	var args []string

	switch runtime.GOOS {
	case "darwin":
		command = "open"
		args = []string{browserURL}
	case "linux":
		command = "xdg-open"
		args = []string{browserURL}
	case "windows":
		command = "cmd"
		args = []string{"/c", "start", "", browserURL}
	default:
		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
	}

	cmd := exec.CommandContext(ctx, command, args...)
	if err := cmd.Start(); err != nil {
		return fmt.Errorf("start browser command %q: %w", command, err)
	}

	if err := cmd.Process.Release(); err != nil {
		return fmt.Errorf("release browser process: %w", err)
	}

	return nil
}

//go:build integration

package integration

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"os/exec"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

func TestLogin_SavesTokenAfterApproval(t *testing.T) {
	t.Parallel()

	type state struct {
		sync.Mutex
		approved bool
		polls    int
	}

	serverState := &state{}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch {
		case r.Method == http.MethodPost && r.URL.Path == "/oauth/device/code":
			writeJSON(t, w, http.StatusOK, map[string]any{
				"device_code":               "device-123",
				"user_code":                 "ABCD-EFGH",
				"verification_uri":          serverURLWithPath(r, "/approve"),
				"verification_uri_complete": serverURLWithPath(r, "/approve?code=ABCD-EFGH"),
				"expires_in":                10,
				"interval":                  1,
			})
		case r.Method == http.MethodPost && r.URL.Path == "/oauth/token":
			serverState.Lock()
			serverState.polls++
			approved := serverState.approved
			serverState.Unlock()

			if !approved {
				writeJSON(t, w, http.StatusBadRequest, map[string]any{"error": "authorization_pending"})
				return
			}

			writeJSON(t, w, http.StatusOK, map[string]any{"access_token": "local-token", "token_type": "Bearer", "expires_in": 3600, "scope": "cli"})
		case r.Method == http.MethodPost && r.URL.Path == "/approve":
			serverState.Lock()
			serverState.approved = true
			serverState.Unlock()
			writeJSON(t, w, http.StatusOK, map[string]any{"success": true})
		default:
			http.NotFound(w, r)
		}
	}))
	defer server.Close()

	proc := runLoginProcess(t, server.URL)

	approvalURL, deviceCode := waitForLoginPrompt(t, proc.stdout)
	if deviceCode != "ABCD-EFGH" {
		t.Fatalf("device code = %q, want %q", deviceCode, "ABCD-EFGH")
	}

	if !strings.HasPrefix(approvalURL, server.URL+"/") {
		t.Fatalf("approval URL = %q, want prefix %q", approvalURL, server.URL+"/")
	}

	approveReq, reqErr := http.NewRequest(http.MethodPost, approvalURL, http.NoBody)
	if reqErr != nil {
		t.Fatalf("create approve request: %v", reqErr)
	}

	approveResp, doErr := http.DefaultClient.Do(approveReq)
	if doErr != nil {
		t.Fatalf("approve request failed: %v", doErr)
	}
	_ = approveResp.Body.Close()

	output, waitErr := proc.wait()
	if waitErr != nil {
		t.Fatalf("login command failed: %v\nOutput:\n%s", waitErr, output)
	}

	if !strings.Contains(output, "Waiting for approval...") {
		t.Fatalf("output missing wait message:\n%s", output)
	}

	if !strings.Contains(output, "Login complete.") {
		t.Fatalf("output missing login complete message (token save likely failed):\n%s", output)
	}

	serverState.Lock()
	polls := serverState.polls
	serverState.Unlock()
	if polls == 0 {
		t.Fatal("expected at least one poll request")
	}
}

func TestLogin_ExpiredFlow(t *testing.T) {
	t.Parallel()

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch {
		case r.Method == http.MethodPost && r.URL.Path == "/oauth/device/code":
			writeJSON(t, w, http.StatusOK, map[string]any{
				"device_code":               "device-expired",
				"user_code":                 "WXYZ-0000",
				"verification_uri":          serverURLWithPath(r, "/approve"),
				"verification_uri_complete": serverURLWithPath(r, "/approve?code=WXYZ-0000"),
				"expires_in":                10,
				"interval":                  1,
			})
		case r.Method == http.MethodPost && r.URL.Path == "/oauth/token":
			writeJSON(t, w, http.StatusBadRequest, map[string]any{"error": "expired_token"})
		default:
			http.NotFound(w, r)
		}
	}))
	defer server.Close()

	proc := runLoginProcess(t, server.URL)
	_, _ = waitForLoginPrompt(t, proc.stdout)

	output, err := proc.wait()
	if err == nil {
		t.Fatalf("expected login to fail for expired flow\nOutput:\n%s", output)
	}

	if !strings.Contains(output, "device authorization expired") {
		t.Fatalf("expected expired message, got:\n%s", output)
	}

	if strings.Contains(output, "Login complete.") {
		t.Fatal("output should NOT contain login complete for expired flow")
	}
}

func TestLogin_DeniedFlow(t *testing.T) {
	t.Parallel()

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch {
		case r.Method == http.MethodPost && r.URL.Path == "/oauth/device/code":
			writeJSON(t, w, http.StatusOK, map[string]any{
				"device_code":               "device-denied",
				"user_code":                 "QRST-9999",
				"verification_uri":          serverURLWithPath(r, "/approve"),
				"verification_uri_complete": serverURLWithPath(r, "/approve?code=QRST-9999"),
				"expires_in":                10,
				"interval":                  1,
			})
		case r.Method == http.MethodPost && r.URL.Path == "/oauth/token":
			writeJSON(t, w, http.StatusBadRequest, map[string]any{"error": "access_denied"})
		default:
			http.NotFound(w, r)
		}
	}))
	defer server.Close()

	proc := runLoginProcess(t, server.URL)
	_, _ = waitForLoginPrompt(t, proc.stdout)

	output, err := proc.wait()
	if err == nil {
		t.Fatalf("expected login to fail for denied flow\nOutput:\n%s", output)
	}

	if !strings.Contains(output, "device authorization denied") {
		t.Fatalf("expected denied message, got:\n%s", output)
	}

	if strings.Contains(output, "Login complete.") {
		t.Fatal("output should NOT contain login complete for denied flow")
	}
}

type loginProcess struct {
	stdout *bufio.Reader
	waitFn func() (string, error)
}

func runLoginProcess(t *testing.T, apiBaseURL string) *loginProcess {
	t.Helper()

	env := NewTestEnv(t)

	cmd := exec.Command(getTestBinary(), "login", "--print-browser-url", "--insecure-http-auth")
	cmd.Dir = env.RepoDir
	cmd.Env = append(testutil.GitIsolatedEnv(),
		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+env.ClaudeProjectDir,
		"ENTIRE_TEST_GEMINI_PROJECT_DIR="+env.GeminiProjectDir,
		"ENTIRE_TEST_OPENCODE_PROJECT_DIR="+env.OpenCodeProjectDir,
		"ENTIRE_TEST_TTY=0",
		"ENTIRE_API_BASE_URL="+apiBaseURL,
	)

	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		t.Fatalf("StdoutPipe() error = %v", err)
	}

	var stderr strings.Builder
	cmd.Stderr = &stderr

	if err := cmd.Start(); err != nil {
		t.Fatalf("cmd.Start() error = %v", err)
	}

	reader := bufio.NewReader(stdoutPipe)

	return &loginProcess{
		stdout: reader,
		waitFn: func() (string, error) {
			stdoutBytes, readErr := io.ReadAll(reader)
			waitErr := cmd.Wait()
			return string(stdoutBytes) + stderr.String(), errors.Join(readErr, waitErr)
		},
	}
}

func (p *loginProcess) wait() (string, error) {
	return p.waitFn()
}

func waitForLoginPrompt(t *testing.T, stdout *bufio.Reader) (string, string) {
	t.Helper()

	deadline := time.Now().Add(10 * time.Second)
	var approvalURL string
	var deviceCode string

	for time.Now().Before(deadline) {
		line, err := stdout.ReadString('\n')
		if err != nil {
			t.Fatalf("read login output: %v", err)
		}

		line = strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(line, "Device code: "):
			deviceCode = strings.TrimPrefix(line, "Device code: ")
		case strings.HasPrefix(line, "Approval URL: "):
			approvalURL = strings.TrimPrefix(line, "Approval URL: ")
		}

		if approvalURL != "" && deviceCode != "" {
			return approvalURL, deviceCode
		}
	}

	t.Fatal("timed out waiting for login prompt output")
	return "", ""
}

func writeJSON(t *testing.T, w http.ResponseWriter, status int, body map[string]any) {
	t.Helper()
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(body); err != nil {
		t.Fatalf("Encode() error = %v", err)
	}
}

func serverURLWithPath(r *http.Request, path string) string {
	return fmt.Sprintf("http://%s%s", r.Host, path)
}

